-- CABO Artist Hub Phase 2, additive and idempotent.
CREATE TABLE IF NOT EXISTS hub_accounts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,display_name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('customer','artist','manager')),verified_at TIMESTAMPTZ,disabled_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE hub_accounts ADD COLUMN IF NOT EXISTS email_verified_at TIMESTAMPTZ;
CREATE TABLE IF NOT EXISTS hub_sessions (token_hash TEXT PRIMARY KEY,account_id UUID NOT NULL REFERENCES hub_accounts(id),expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS artist_account_memberships (account_id UUID NOT NULL REFERENCES hub_accounts(id),artist_id BIGINT NOT NULL REFERENCES artists(id),access_role TEXT NOT NULL CHECK(access_role IN ('owner','editor','viewer')),PRIMARY KEY(account_id,artist_id));
ALTER TABLE booking_enquiries ADD COLUMN IF NOT EXISTS customer_account_id UUID REFERENCES hub_accounts(id);
CREATE TABLE IF NOT EXISTS account_verification_tokens (token_hash TEXT PRIMARY KEY,account_id UUID NOT NULL REFERENCES hub_accounts(id),expires_at TIMESTAMPTZ NOT NULL,consumed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS booking_contracts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),booking_id UUID NOT NULL REFERENCES booking_enquiries(id),title TEXT NOT NULL,terms TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','sent','accepted','void')),signed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS booking_invoices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),booking_id UUID NOT NULL REFERENCES booking_enquiries(id),invoice_number TEXT NOT NULL UNIQUE,currency CHAR(3) NOT NULL DEFAULT 'ZAR',amount_cents BIGINT NOT NULL CHECK(amount_cents>=0),paid_cents BIGINT NOT NULL DEFAULT 0 CHECK(paid_cents>=0),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','issued','partially_paid','paid','void')),due_date DATE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(paid_cents<=amount_cents));
CREATE TABLE IF NOT EXISTS invoice_payment_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),invoice_id UUID NOT NULL REFERENCES booking_invoices(id),provider TEXT NOT NULL,provider_event_id TEXT NOT NULL,amount_cents BIGINT NOT NULL CHECK(amount_cents>0),received_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(provider,provider_event_id));
CREATE TABLE IF NOT EXISTS hub_notifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),account_id UUID REFERENCES hub_accounts(id),booking_id UUID REFERENCES booking_enquiries(id),channel TEXT NOT NULL CHECK(channel IN ('in_app','email')),subject TEXT NOT NULL,body TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','sent','failed')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),delivered_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS social_provider_connections (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),artist_id BIGINT NOT NULL REFERENCES artists(id),platform TEXT NOT NULL,provider_account_ref TEXT NOT NULL,token_secret_ref TEXT NOT NULL,granted_scopes TEXT[] NOT NULL DEFAULT '{}',last_synced_at TIMESTAMPTZ,connected_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(artist_id,platform,provider_account_ref));
CREATE TABLE IF NOT EXISTS social_provider_metrics (id BIGSERIAL PRIMARY KEY,connection_id UUID NOT NULL REFERENCES social_provider_connections(id),observed_at TIMESTAMPTZ NOT NULL,followers BIGINT CHECK(followers>=0),reach BIGINT CHECK(reach>=0),impressions BIGINT CHECK(impressions>=0),engagement BIGINT CHECK(engagement>=0),source_kind TEXT NOT NULL DEFAULT 'official_api',UNIQUE(connection_id,observed_at));
CREATE TABLE IF NOT EXISTS hub_operational_checks (id BIGSERIAL PRIMARY KEY,check_name TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN ('pass','fail','warn')),details TEXT,checked_at TIMESTAMPTZ NOT NULL DEFAULT now());
